small.fason:
ScaleTurnCalendar({
  "stCloseGainController": BscCloseGainController({
    "cgcInputs": GMap({
      "f0": AdjCloseVerticalDistanceInput({
        "acvdLabel": 'adistance',
        "acvdXStepTimes": 0.1,
        "acvdDisTimes": 100
      })
    }),
    "cgcCombine": InputCombineIfClose({
      "icicLine": 0   # 距离阈值
    })
  }),
  "stMembershipLine": 0.3,
  "stRnd2ChooseTurn": ChooseMaxExtraPoint({
    "cmepOccupy": 0
  }),
  "specTerm": 'S',
  "falter": RctZigWithStatus({
    # ZigZag
    "zig": ZigZag({
      # 要计算zigzag的特征, 一般是k线收盘价, 要求有uti数据
      "featIn": KLine({
        "freq": '30m'
      }) % ('closeUti as uti', 'close as value'),
      "retracePct": 0.1   # 反转百分比
    })
  }),
  "fcheck": RctZigWithStatus({
    # ZigZag
    "zig": ZigZag({
      # 要计算zigzag的特征, 一般是k线收盘价, 要求有uti数据
      "featIn": KLine({
        "freq": '30m'
      }) % ('closeUti as uti', 'close as value'),
      "retracePct": 0.1   # 反转百分比
    })
  }),
  "fisSystem": T1FisSystem({
    "Name": 'T1FIS',
    "Config": T1FisSystemConfig({
      "type1": 'mamdani',
      "version1": '2.0',
      "andMethod1": 'min',
      "orMethod1": 'max',
      "impMethod1": 'min',
      "aggMethod1": 'max',
      "defuzzMethod1": 'centroid'
    }),
    "Inputs": GMap({
      "adistance": OneUseGaussmfInOrOutPut({
        "range": (0, 10),
        "mf_name": ['VS', 'S', 'M', 'L'],
        "MfValueFunc": GaussMFs({
          "overlap": 0.2
        })
      })
    }),
    "Outputs": GMap({
      "closegain": OneUseGaussmfInOrOutPut({
        "range": (0, 1),
        "mf_name": ['VS', 'S', 'M', 'L'],
        "MfValueFunc": GaussMFs({
          "overlap": 0.2
        })
      })
    }),
    "Rules": OneSetRules({
      "rules": GMap({
        "f0": IfAll({
          "inputs": {
            "adistance": 'L'
          },
          "outputs": {
            "closegain": 'L'
          },
          "weight": 1
        }),
        "f1": IfAll({
          "inputs": {
            "adistance": 'M'
          },
          "outputs": {
            "closegain": 'M'
          },
          "weight": 1
        }),
        "f2": IfAll({
          "inputs": {
            "adistance": 'S'
          },
          "outputs": {
            "closegain": 'S'
          },
          "weight": 1
        }),
        "f3": IfAll({
          "inputs": {
            "adistance": 'VS'
          },
          "outputs": {
            "closegain": 'VS'
          },
          "weight": 1
        })
      })
    })
  })
})

